mapper.select:
SELECT r.id, r.refund_no, r.order_id, o.order_no, r.payment_id, r.member_id, r.refund_amount, r.refund_type, r.refund_reason, r.refund_method, r.status, r.audit_by, r.audit_at, r.operator_id, r.created_at FROM refund_record r LEFT JOIN orders o ON r.order_id = o.id AND o.deleted_at IS NULL WHERE r.deleted_at IS NULL
AND r.order_id = #{orderId}
AND r.status = #{status}
AND r.created_at >= #{startTime}
AND r.created_at <= #{endTime}
ORDER BY r.created_at DESC
